def is_power_of_5(n):
    if n <= 0:
        return False
    while n > 1 and n % 5 == 0:
        n //= 5
    return n == 1

b = 369
try:
    b_pow_4 = b**4
    target = b_pow_4 + 4
    print(f"369^4 + 4 = {target}")
    print(f"Is {target} a power of 5? {is_power_of_5(target)}")
except OverflowError:
    print("Calculation overflowed.")
